import{_ as a,o,c as s,a0 as t}from"./chunks/framework.C3yZ6M33.js";const g=JSON.parse('{"title":"Distribution — bundle refs, store, cache, verbs","description":"","frontmatter":{},"headers":[],"relativePath":"reference/distribution.md","filePath":"reference/distribution.md"}'),r={name:"reference/distribution.md"};function n(i,e,c,d,l,p){return o(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="distribution-—-bundle-refs-store-cache-verbs" tabindex="-1">Distribution — bundle refs, store, cache, verbs <a class="header-anchor" href="#distribution-—-bundle-refs-store-cache-verbs" aria-label="Permalink to &quot;Distribution — bundle refs, store, cache, verbs&quot;">​</a></h1><p>ADR-0079. A <em>bundle</em> is a manifest (<code>peregrin-bundle.yaml</code> / <code>.yml</code> / <code>.toml</code>) plus a payload of workflows, <code>.node.yml</code>, <code>.driver.yml</code> and <code>.field.yml</code> files. <code>peregrin install &lt;ref&gt;</code> fetches one from the filesystem, a git remote, or an HTTP tarball, unpacks it into a local store, and records the resolved pin.</p><h2 id="ref-grammar" tabindex="-1">Ref grammar <a class="header-anchor" href="#ref-grammar" aria-label="Permalink to &quot;Ref grammar&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>peregrin install ./ci-gate                                  # filepath — dev loop</span></span>
<span class="line"><span>peregrin install git:9aia/peregrin/libraries/ci-gate        # shorthand (github), default branch</span></span>
<span class="line"><span>peregrin install git:github.com/9aia/peregrin//libraries/ci-gate#v0.2.0</span></span>
<span class="line"><span>peregrin install git:git@github.com:9aia/peregrin//libraries/ci-gate#main</span></span>
<span class="line"><span>peregrin install git:https://gitlab.com/grp/sub/repo//dir   # any git url</span></span>
<span class="line"><span>peregrin install https://9aia.com/bundles/ci-gate-0.2.tgz   # non-git tarball</span></span></code></pre></div><ul><li><strong><code>git:&lt;url&gt;[//&lt;subdir&gt;][#&lt;ref&gt;]</code></strong> — <code>//</code> (go-getter convention) splits the repo path from the in-repo path; it&#39;s <em>required</em> for nested groups because bare <code>a/b/c/d</code> is ambiguous. <code>#ref</code> is a branch, tag or sha — the git ref <em>is</em> the version pin; the resolved commit sha is recorded regardless.</li><li><strong>Without <code>//</code></strong>, a two-segment prefix is the repo and the remainder is the in-repo path — so <code>git:9aia/peregrin/libraries/ci-gate</code> clones <code>github.com/9aia/peregrin</code> and takes <code>libraries/ci-gate</code> from it. This rule only applies to <em>shorthand</em> paths: anything containing <code>://</code>, scp-style <code>host:path</code> (<code>git@…:</code>), or an explicit local path (<code>/x</code>, <code>~/x</code>, <code>./x</code>) parses whole.</li><li><strong>Shorthand</strong> — <code>org/repo</code> defaults to <code>github.com</code>; <code>host/org/repo</code> becomes <code>https://host/org/repo</code>. <code>git@…</code>, <code>ssh://</code>, <code>file://</code> and local paths pass through.</li><li><strong><code>./path</code>, <code>/path</code>, <code>~/path</code>, <code>nested/path</code></strong> → <code>source-fs</code>. A directory copies its payload (<code>.git/</code> excluded); a <code>.tgz</code>/<code>.tar.gz</code>/ <code>.tar</code> file unpacks.</li><li><strong><code>http(s)://…​.tgz|.tar.gz</code></strong> → <code>source-http</code>, with an optional <code>#sha256:&lt;hex&gt;</code> (or <code>#sha256=&lt;hex&gt;</code>) digest pin verified on fetch.</li></ul><h2 id="store-fetch-cache" tabindex="-1">Store + fetch cache <a class="header-anchor" href="#store-fetch-cache" aria-label="Permalink to &quot;Store + fetch cache&quot;">​</a></h2><ul><li><strong>Store</strong> — <code>~/.local/share/peregrin/store/&lt;name&gt;@&lt;version-or-sha&gt;/</code> holds unpacked bundles. <code>name</code> aliases the entry so campaigns and <code>peregrin run</code> can resolve <code>bundle:&lt;name&gt;</code> refs. Each entry carries <code>.peregrin-store.json</code>: the source ref, resolved sha (commit sha or <code>sha256:</code> digest), payload digest, and installed-at.</li><li><strong>Fetch cache</strong> — <code>~/.cache/peregrin/fetch/&lt;key&gt;/</code> is content-addressed (<code>git-&lt;sha&gt;</code> for git, <code>sha256-&lt;hex&gt;</code> for content digests). Install is two-phase fetch→unpack: a warm cache makes repeat installs and air-gapped nodes free — a ref whose pin is already known (a <code>#sha</code> or a <code>#sha256:</code> tarball digest) skips the transport entirely on a cache hit.</li><li><code>remove</code> drops only the store entry; the cache evicts by age or <code>cache clean --all</code>, never by <code>remove</code>.</li></ul><h2 id="include-composition" tabindex="-1"><code>include:</code> composition <a class="header-anchor" href="#include-composition" aria-label="Permalink to &quot;\`include:\` composition&quot;">​</a></h2><p>A manifest may declare <code>include: […]</code> — base bundles whose payloads deep-merge <em>under</em> the local one. Entries are installed store names (<code>name</code> or <code>name@version</code>) or source refs (installed on demand). Semantics come from the ported loader: local wins, dicts merge per-key, arrays concatenate local-first, and node <code>id</code> collisions dedupe keeping the local definition — so an overlay that redefines a node can&#39;t double-fire it. Earlier <code>include:</code> entries outrank later ones. Conflicting <code>.yaml</code>/<code>.yml</code>/<code>.json</code> files merge document-wise; every other conflict resolves whole-file.</p><h2 id="verbs" tabindex="-1">Verbs <a class="header-anchor" href="#verbs" aria-label="Permalink to &quot;Verbs&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>peregrin install &lt;ref&gt;          # fetch → store (+ alias)</span></span>
<span class="line"><span>peregrin remove &lt;name&gt;          # drop store entry; cache untouched</span></span>
<span class="line"><span>peregrin list                   # installed bundles, refs, digests</span></span>
<span class="line"><span>peregrin info &lt;name&gt;            # manifest, source ref, resolved sha, size</span></span>
<span class="line"><span>peregrin update &lt;name&gt;|--all    # re-resolve the recorded source ref</span></span>
<span class="line"><span>peregrin pin &lt;name&gt; &lt;ref&gt;       # retarget the recorded ref</span></span>
<span class="line"><span>peregrin verify &lt;name&gt;          # digest-check store contents vs recorded sha</span></span>
<span class="line"><span>peregrin cache clean [--all]    # evict fetch cache (--days N, default 30)</span></span>
<span class="line"><span>peregrin bundle pack &lt;dir&gt;      # authoring — dir + manifest → .tgz</span></span></code></pre></div><ul><li><code>update</code> re-resolves the recorded source ref — the upgrade path for moving refs like branches; pinned tags/shas re-confirm.</li><li><code>pin</code> retargets the recorded ref and refetches when the resolved digest differs.</li><li><code>verify</code> recomputes the payload digest and fails on mismatch.</li><li><code>bundle pack</code> writes <code>&lt;name&gt;-&lt;version&gt;.tgz</code> (or <code>--out</code>), installable via <code>peregrin install ./x.tgz</code> or an <code>https://</code> URL.</li><li>Names accept <code>name</code> or <code>name@version</code>; a bare name with several installed versions is an ambiguity error.</li></ul>`,12)])])}const m=a(r,[["render",n]]);export{g as __pageData,m as default};
